import{I as t,o as e,c as o,J as a}from"./chunks/framework.DBa8tQ-e.js";const h=JSON.parse('{"title":"Tool、RAG、MCP 与 Agent：先把职责分清楚","description":"用知识库问答场景理解 Tool、RAG、MCP 和 Agent 的分工，以及 Host、Client、Server 和三类服务能力。","frontmatter":{"title":"Tool、RAG、MCP 与 Agent：先把职责分清楚","date":"2026-11-06","description":"用知识库问答场景理解 Tool、RAG、MCP 和 Agent 的分工，以及 Host、Client、Server 和三类服务能力。","category":"AI 学习","tags":["MCP","Agent","Tool Calling","RAG"],"folder":"ai/highlights"},"headers":[{"level":2,"title":"四个概念，四种职责","slug":"四个概念四种职责","link":"#四个概念四种职责","children":[]},{"level":2,"title":"Host、Client、Server 怎样配合","slug":"hostclientserver-怎样配合","link":"#hostclientserver-怎样配合","children":[]},{"level":2,"title":"Tools、Resources、Prompts 分别提供什么","slug":"toolsresourcesprompts-分别提供什么","link":"#toolsresourcesprompts-分别提供什么","children":[]},{"level":2,"title":"一次工具调用怎样完成闭环","slug":"一次工具调用怎样完成闭环","link":"#一次工具调用怎样完成闭环","children":[]},{"level":2,"title":"本地与远程连接怎么选","slug":"本地与远程连接怎么选","link":"#本地与远程连接怎么选","children":[]}],"relativePath":"posts/mcp-tools-rag-agent.md","filePath":"posts/mcp-tools-rag-agent.md"}'),l={name:"posts/mcp-tools-rag-agent.md"};function n(r,s,p,c,i,d){return e(),o("div",null,[...s[0]||(s[0]=[a(`<h1 id="toolragmcp-与-agent先把职责分清楚" tabindex="-1">Tool、RAG、MCP 与 Agent：先把职责分清楚 <a class="header-anchor" href="#toolragmcp-与-agent先把职责分清楚" aria-label="Permalink to &quot;Tool、RAG、MCP 与 Agent：先把职责分清楚&quot;">​</a></h1><p>这几个概念经常出现在同一个 AI 项目里，学习时容易混成一团。用“查询知识库并回答问题”这个例子，可以把它们放回各自的位置。</p><h2 id="四个概念四种职责" tabindex="-1">四个概念，四种职责 <a class="header-anchor" href="#四个概念四种职责" aria-label="Permalink to &quot;四个概念，四种职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>主要解决的问题</th><th>知识库问答中的例子</th></tr></thead><tbody><tr><td>Tool</td><td>提供一个可调用的具体能力</td><td><code>search_notes(query)</code> 搜索笔记</td></tr><tr><td>RAG</td><td>把检索到的资料用于生成回答</td><td>找到相关段落后，带着来源组织答案</td></tr><tr><td>MCP</td><td>统一应用与外部能力的通信接口</td><td>通过标准接口发现并调用笔记搜索能力</td></tr><tr><td>Agent</td><td>根据目标和上下文决定下一步动作</td><td>决定是否搜索、用什么关键词、是否继续查询</td></tr></tbody></table><p>固定工作流同样可以使用检索和工具；只有一个搜索接口，也不意味着系统已经具备多步自主决策能力。MCP 接入后，应用仍需负责模型调用、上下文组织和实际工作流。<a href="https://modelcontextprotocol.io/docs/2026-07-28/learn/architecture" target="_blank" rel="noreferrer">MCP 官方架构说明</a>明确将协议范围限定在上下文交换。</p><h2 id="hostclientserver-怎样配合" tabindex="-1">Host、Client、Server 怎样配合 <a class="header-anchor" href="#hostclientserver-怎样配合" aria-label="Permalink to &quot;Host、Client、Server 怎样配合&quot;">​</a></h2><p>原笔记把 MCP 比作通用接口，这有助于理解复用价值。进一步看实现，可以分成三层：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>用户</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Host：用户使用的 AI 应用</span></span>
<span class="line"><span>  ├─ Client A → 笔记搜索 Server</span></span>
<span class="line"><span>  └─ Client B → 其他业务 Server</span></span></code></pre></div><p>Host 管理模型、交互界面和上下文。Client 是 Host 内部与某个 Server 通信的组件。Server 对外提供具体的数据或功能，可以运行在本地，也可以是远程服务。这个结构与模型本身部署在哪里是两件事。<a href="https://modelcontextprotocol.io/docs/2026-07-28/learn/architecture#participants" target="_blank" rel="noreferrer">官方参与者定义</a>给出了三者的关系。</p><p>“统一接口”意味着减少重复适配工作，实际使用仍要核对宿主支持的协议版本、传输方式和能力。宿主使用什么配置文件、如何管理进程，也属于宿主自己的实现。</p><h2 id="toolsresourcesprompts-分别提供什么" tabindex="-1">Tools、Resources、Prompts 分别提供什么 <a class="header-anchor" href="#toolsresourcesprompts-分别提供什么" aria-label="Permalink to &quot;Tools、Resources、Prompts 分别提供什么&quot;">​</a></h2><p>MCP Server 常见的三类能力可以这样区分：</p><ul><li><strong>Tools</strong>：执行某个操作，例如按关键词搜索、查询一条业务记录。</li><li><strong>Resources</strong>：提供上下文数据，例如一份文档正文或数据库结构。</li><li><strong>Prompts</strong>：提供可复用的交互模板，例如一套文档总结提示词。</li></ul><p>三者的典型控制方分别是模型、应用和用户。这里的“模型控制工具”是指模型可以提出调用请求；真正执行操作的是应用及服务端代码。具体交互和授权方式由应用实现。<a href="https://modelcontextprotocol.io/docs/2026-07-28/learn/server-concepts" target="_blank" rel="noreferrer">MCP 服务能力文档</a>对这些边界有详细介绍。</p><p>一个工具定义可以长这样，下面只是结构示意：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">{</span></span>
<span class="line"><span style="color:#005CC5;">  &quot;name&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;search_notes&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#005CC5;">  &quot;description&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;按关键词检索公开技术笔记，返回标题、摘要和来源链接&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#005CC5;">  &quot;inputSchema&quot;</span><span style="color:#24292E;">: {</span></span>
<span class="line"><span style="color:#005CC5;">    &quot;type&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;object&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#005CC5;">    &quot;properties&quot;</span><span style="color:#24292E;">: {</span></span>
<span class="line"><span style="color:#005CC5;">      &quot;query&quot;</span><span style="color:#24292E;">: { </span><span style="color:#005CC5;">&quot;type&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;string&quot;</span><span style="color:#24292E;"> }</span></span>
<span class="line"><span style="color:#24292E;">    },</span></span>
<span class="line"><span style="color:#005CC5;">    &quot;required&quot;</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&quot;query&quot;</span><span style="color:#24292E;">],</span></span>
<span class="line"><span style="color:#005CC5;">    &quot;additionalProperties&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">false</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre></div><p>工具描述需要说明输入和结果的含义。“搜索公开技术笔记”比笼统的“处理数据”更容易让调用方判断何时使用。</p><h2 id="一次工具调用怎样完成闭环" tabindex="-1">一次工具调用怎样完成闭环 <a class="header-anchor" href="#一次工具调用怎样完成闭环" aria-label="Permalink to &quot;一次工具调用怎样完成闭环&quot;">​</a></h2><p>以“找到关于事务传播的笔记并总结”为例：</p><ol><li>应用取得工具定义，把相关能力告诉模型。</li><li>模型提出 <code>search_notes</code> 调用请求及结构化参数。</li><li>应用校验请求，交由对应的 Server 执行搜索。</li><li>应用把搜索结果放回后续上下文。</li><li>模型根据结果继续回答，或者提出下一次查询。</li></ol><p>因此，拿到 <code>tool_calls</code> 只是获得了调用意图。查询是否执行、结果是否返回、最终答案是否完整，是后续几个独立步骤。这也是只写 <code>bind_tools()</code> 后，不能把第一轮模型输出当作最终业务结果的原因。</p><h2 id="本地与远程连接怎么选" tabindex="-1">本地与远程连接怎么选 <a class="header-anchor" href="#本地与远程连接怎么选" aria-label="Permalink to &quot;本地与远程连接怎么选&quot;">​</a></h2><p>原笔记涉及 <code>stdio</code> 和 Streamable HTTP：前者通过本地进程的标准输入输出通信，适合本地工具；后者通过 HTTP 连接，适合独立部署的服务。协议具体要求应以所使用的版本和 SDK 文档为准。<a href="https://modelcontextprotocol.io/docs/2026-07-28/learn/architecture#transport-layer" target="_blank" rel="noreferrer">官方传输层概述</a>介绍了两者。</p><p>选型时先回答三个实际问题：能力运行在哪里、谁负责它的生命周期、应用如何取得访问权限。连接成功之后，再验证返回结构、异常处理和工作流是否闭环。</p><p>如果只有一个内部项目需要调用一个普通函数，直接封装 Tool 可能已经够用。多个宿主需要复用同一组能力时，再评估 MCP 的适配成本和收益。知识检索是否采用 RAG、后续是否交给 Agent 决策，可以分别判断。</p><blockquote><p>整理自个人 AI 学习笔记《MCP 模型上下文协议》《Tool Calling &amp; Function Calling》。本文保留概念与调用流程，去掉未经验证的 SDK 接入片段，补充应用执行工具和宿主适配的边界。</p></blockquote>`,26)])])}const g=t(l,[["render",n]]);export{h as __pageData,g as default};
